import { NextRequest, NextResponse } from "next/server";

export const runtime = "nodejs";

const SIMULATED_STREAM_CHUNKS = [
  "DSGKX Neural Engine initialized. ",
  "In modern autoregressive systems, ",
  "each token is generated by evaluating ",
  "high-dimensional attention heads across ",
  "the cached key-value context. ",
  "\n\n```python\n# Scaled Dot-Product Attention\ndef attention(Q, K, V, mask=None):\n    scores = torch.matmul(Q, K.transpose(-2, -1)) / math.sqrt(d_k)\n    if mask is not None:\n        scores = scores.masked_fill(mask == 0, -1e9)\n    weights = F.softmax(scores, dim=-1)\n    return torch.matmul(weights, V)\n```\n\n",
  "To execute live inference with your own model weights, ",
  "please enter your Groq API key (starts with 'gsk_') or xAI Grok key ('xai-') ",
  "in the right-hand Parameters panel. ",
  "Live requests will stream at 300+ tokens/sec directly from the neural cluster.",
];

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const {
      provider = "groq", // "groq" | "xai" | "demo" | "custom"
      apiKey = "",
      model = "llama-3.3-70b-versatile",
      messages = [],
      temperature = 0.7,
      max_tokens = 2048,
      top_p = 1.0,
      stream = true,
      customBaseUrl = "",
    } = body;

    const trimmedKey = (apiKey || "").trim();

    // If demo mode or no key provided, return simulated stream
    if (provider === "demo" || !trimmedKey) {
      if (stream) {
        const encoder = new TextEncoder();
        const demoStream = new ReadableStream({
          async start(controller) {
            for (const chunk of SIMULATED_STREAM_CHUNKS) {
              const data = JSON.stringify({
                choices: [
                  {
                    delta: { content: chunk },
                    index: 0,
                    finish_reason: null,
                  },
                ],
              });
              controller.enqueue(encoder.encode(`data: ${data}\n\n`));
              await new Promise((res) => setTimeout(res, 60));
            }
            controller.enqueue(encoder.encode("data: [DONE]\n\n"));
            controller.close();
          },
        });

        return new Response(demoStream, {
          headers: {
            "Content-Type": "text/event-stream; charset=utf-8",
            "Cache-Control": "no-cache, no-transform",
            Connection: "keep-alive",
          },
        });
      }

      return NextResponse.json({
        choices: [
          {
            message: {
              role: "assistant",
              content: SIMULATED_STREAM_CHUNKS.join(""),
            },
          },
        ],
      });
    }

    // Determine target endpoint based on key format or provider selection
    let endpoint = "https://api.groq.com/openai/v1/chat/completions";
    if (provider === "xai" || trimmedKey.startsWith("xai-") || model.toLowerCase().startsWith("grok")) {
      endpoint = "https://api.x.ai/v1/chat/completions";
    } else if (provider === "custom" && customBaseUrl) {
      endpoint = customBaseUrl.endsWith("/chat/completions")
        ? customBaseUrl
        : `${customBaseUrl.replace(/\/$/, "")}/chat/completions`;
    }

    const payload: Record<string, unknown> = {
      model,
      messages,
      temperature,
      max_tokens,
      top_p,
      stream,
    };

    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${trimmedKey}`,
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      const errText = await response.text();
      let errMsg = `Upstream error (${response.status}): ${response.statusText}`;
      try {
        const parsed = JSON.parse(errText);
        if (parsed.error?.message) {
          errMsg = parsed.error.message;
        }
      } catch {
        errMsg = errText || errMsg;
      }
      return NextResponse.json({ error: errMsg }, { status: response.status });
    }

    if (stream && response.body) {
      const clientStream = new ReadableStream({
        async start(controller) {
          const reader = response.body!.getReader();
          try {
            while (true) {
              const { done, value } = await reader.read();
              if (done) break;
              controller.enqueue(value);
            }
          } catch (err) {
            controller.error(err);
          } finally {
            controller.close();
          }
        },
      });

      return new Response(clientStream, {
        headers: {
          "Content-Type": "text/event-stream; charset=utf-8",
          "Cache-Control": "no-cache, no-transform",
          Connection: "keep-alive",
        },
      });
    }

    const json = await response.json();
    return NextResponse.json(json);
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown server error";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
